using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetSettings()
    {
        var config = new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up an environment variable by name.")]
    public static string GetEnvVariable(
        [Description("The environment variable name to look up")] string name)
    {
        var value = Environment.GetEnvironmentVariable(name);
        return value is not null
            ? $"{name}={value}"
            : $"Environment variable '{name}' is not set.";
    }

    [McpServerTool, Description("Return the server's current UTC time and uptime info.")]
    public static string GetServerStatus()
    {
        return $"Server time (UTC): {DateTime.UtcNow:O}, " +
               $"OS: {Environment.OSVersion}, " +
               $"Processors: {Environment.ProcessorCount}";
    }
}

